INSERT IGNORE INTO destinations(name,description,image_url) VALUES ('Kanyakumari','Ocean views, coastal heritage and memorials.','https://images.unsplash.com/photo-1500534623283-312aade485b7?w=1200'),('Goa','Beaches, historic forts and relaxed coastal travel.','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200'),('Delhi','Historic monuments, culture and bustling markets.','https://images.unsplash.com/photo-1587474260584-136574528ed5?w=1200'),('Hyderabad','Royal heritage, monuments and local cuisine.','https://images.unsplash.com/photo-1477587458883-47145ed94245?w=1200'),('Agra','Taj Mahal and Mughal architecture.','https://images.unsplash.com/photo-1564507592333-c60657eea523?w=1200');
