CREATE DATABASE IF NOT EXISTS tripvora CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tripvora;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,phone VARCHAR(20) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,address TEXT NOT NULL,email_verified_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS otp_tokens(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,otp_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,attempts INT NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS destinations(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,description TEXT NOT NULL,image_url VARCHAR(500) DEFAULT '');
CREATE TABLE IF NOT EXISTS attractions(id INT AUTO_INCREMENT PRIMARY KEY,destination_id INT NOT NULL,name VARCHAR(140) NOT NULL,description TEXT NOT NULL,image_url VARCHAR(500) DEFAULT '',entry_price DECIMAL(10,2) NOT NULL DEFAULT 0,duration_minutes INT NOT NULL DEFAULT 90,FOREIGN KEY(destination_id) REFERENCES destinations(id));
CREATE TABLE IF NOT EXISTS hotels(id INT AUTO_INCREMENT PRIMARY KEY,destination_id INT NOT NULL,name VARCHAR(140) NOT NULL,description TEXT NOT NULL,image_url VARCHAR(500) DEFAULT '',rating DECIMAL(2,1) DEFAULT 4.0,price_per_night DECIMAL(10,2) NOT NULL,rooms_total INT NOT NULL DEFAULT 5,active TINYINT(1) DEFAULT 1,FOREIGN KEY(destination_id) REFERENCES destinations(id));
CREATE TABLE IF NOT EXISTS vehicles(id INT AUTO_INCREMENT PRIMARY KEY,destination_id INT NOT NULL,name VARCHAR(140) NOT NULL,vehicle_type ENUM('bike','car') NOT NULL,registration_number VARCHAR(60) NOT NULL UNIQUE,image_url VARCHAR(500) DEFAULT '',price_per_day DECIMAL(10,2) NOT NULL,active TINYINT(1) DEFAULT 1,FOREIGN KEY(destination_id) REFERENCES destinations(id));
CREATE TABLE IF NOT EXISTS trips(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,destination_id INT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,people INT NOT NULL,hotel_id INT NULL,vehicle_id INT NULL,helmet TINYINT(1) DEFAULT 0,attractions_total DECIMAL(10,2) NOT NULL,hotel_total DECIMAL(10,2) NOT NULL,vehicle_total DECIMAL(10,2) NOT NULL,total DECIMAL(10,2) NOT NULL,payment_status ENUM('pending','paid') DEFAULT 'pending',status ENUM('booked','cancelled') DEFAULT 'booked',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(destination_id) REFERENCES destinations(id),FOREIGN KEY(hotel_id) REFERENCES hotels(id),FOREIGN KEY(vehicle_id) REFERENCES vehicles(id),CHECK(end_date>=start_date));
CREATE TABLE IF NOT EXISTS trip_attractions(trip_id INT NOT NULL,attraction_id INT NOT NULL,PRIMARY KEY(trip_id,attraction_id),FOREIGN KEY(trip_id) REFERENCES trips(id),FOREIGN KEY(attraction_id) REFERENCES attractions(id));
CREATE TABLE IF NOT EXISTS reviews(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,hotel_id INT NOT NULL,rating INT NOT NULL,comment TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(hotel_id) REFERENCES hotels(id),CHECK(rating BETWEEN 1 AND 5));
